//! Rust components used by the templates: `<Icon>` (an Iconify name resolved to its
//! compiled SVG) and the reused Svelte components with props (sidebar rows, cards).
use super::{
    Menu, Msg,
    assets::Assets,
    color::*,
    css,
    data::{self, Mix, Playlist},
    icons,
};
use karbon_ui::ui::prelude::*;

/// `<Icon icon="lucide:plus" width={16} />` of `@iconify/svelte`: the Iconify icon as a
/// compiled `<svg src>` (generated by `tools/icons.py`), `width` × `width`, drawn with
/// `currentColor` = the inherited CSS `color` (hover included). `epais` adds the
/// `.sb-icone` stroke of the sidebar icons.
pub struct Icon {
    pub icon: String,
    pub width: f32,
    pub epais: bool,
}
impl Default for Icon {
    fn default() -> Self {
        Self {
            icon: String::new(),
            width: 20.,
            epais: false,
        }
    }
}
impl Component<Assets> for Icon {
    fn render(self, cx: &TemplateContext<'_, Assets>, _: Slots) -> Element {
        let size = self.width * cx.scale;
        icons::svg(cx, &self.icon, self.epais)
            .unwrap_or_else(|| {
                panic!(
                    "icon {} (epais: {}) missing: run tools/icons.py",
                    self.icon, self.epais
                )
            })
            .width(size)
            .height(size)
    }
}

// ─── Reused Svelte components ──────────────────────────────────────────────

/// `ui/titlebar/Titlebar.svelte`: brand, page content (slot), window controls.
#[derive(Default)]
pub struct Titlebar {
    pub avec_sidebar: bool,
    /// The sidebar is collapsed: the button expands it (icon and label follow).
    pub replie: bool,
}
impl Component<Assets> for Titlebar {
    fn render(self, cx: &TemplateContext<'_, Assets>, mut slots: Slots) -> Element {
        ui_file!(
            "ui/titlebar/Titlebar.ui",
            context = cx,
            slots = slots,
            styles = css
        )
    }
}

