/// `sidebar/PlaylistItem.svelte`: a `SidebarRow` for a pinned playlist.
#[derive(Default)]
pub struct PlaylistItem {
    pub playlist: Option<&'static Playlist>,
    /// Collapsed sidebar (`SidebarRow::replie`).
    pub replie: bool,
}
impl Component<Assets> for PlaylistItem {
    fn render(self, cx: &TemplateContext<'_, Assets>, _: Slots) -> Element {
        let p = self.playlist.expect("PlaylistItem needs a playlist");
        ui! {@context(cx); @styles(css);
            <SidebarRow titre={p.nom} sous_titre={p.sous_titre} menu replie={self.replie}>
                <SidebarThumbnail slot="vignette" couvertures={p.couvertures}
                                  couleur={p.couleur} icone={p.icone} />
            </SidebarRow>
        }
    }
}

