/// `sidebar/SidebarButton.svelte`
pub struct SidebarButton {
    pub icon: String,
    pub label: String,
    pub taille: f32,
    pub onclick: Option<Msg>,
}
impl Default for SidebarButton {
    fn default() -> Self {
        Self {
            icon: String::new(),
            label: String::new(),
            taille: 20.,
            onclick: None,
        }
    }
}
impl Component<Assets> for SidebarButton {
    fn render(self, cx: &TemplateContext<'_, Assets>, mut slots: Slots) -> Element {
        let onclick = self.onclick.clone().unwrap_or(Msg::Noop);
        ui_file!(
            "ui/sidebar/SidebarButton.ui",
            context = cx,
            slots = slots,
            styles = css
        )
    }
}
